Gatherer<Integer, ?, Integer> pairwiseMax = Gatherer.ofSequential(
    Acc::new,                                    // initializer: per-partition private state
    (Acc acc, Integer x, Gatherer.Downstream<? super Integer> down) -> {
        if (!acc.buf().isEmpty())
            down.push(Math.max(acc.buf().get(0), x));
        acc.buf().set(0, x);                     // never shared between partitions
        return true;                             // false would stop the upstream
    });
ints.stream().gather(pairwiseMax).gather(Gatherers.windowFixed(2)).toList();
